CREATE TABLE FengTu_PL_Email_Schema_History (version INTEGER PRIMARY KEY, applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE FengTu_PL_Email_Account (id BIGINT AUTO_INCREMENT PRIMARY KEY, display_name VARCHAR(200) NOT NULL, email VARCHAR(320) NOT NULL UNIQUE, encrypted_password LONGTEXT NOT NULL, smtp_host VARCHAR(255) NOT NULL, smtp_port INTEGER NOT NULL, smtp_security VARCHAR(20) NOT NULL, imap_host VARCHAR(255), imap_port INTEGER, imap_security VARCHAR(20), is_default BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE FengTu_PL_Email_Contact (id BIGINT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(320) NOT NULL UNIQUE, nickname VARCHAR(200), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE FengTu_PL_Email_Tag (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(200) NOT NULL UNIQUE);
CREATE TABLE FengTu_PL_Email_Contact_Tag (contact_id BIGINT NOT NULL, tag_id BIGINT NOT NULL, PRIMARY KEY(contact_id, tag_id));
CREATE TABLE FengTu_PL_Email_Mass_Config (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(200) NOT NULL, mode VARCHAR(30) NOT NULL, config_json LONGTEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE FengTu_PL_Email_Pending_Send (id BIGINT AUTO_INCREMENT PRIMARY KEY, confirmation_id VARCHAR(64) NOT NULL UNIQUE, account_id BIGINT NOT NULL, mode VARCHAR(30) NOT NULL, snapshot_json LONGTEXT NOT NULL, status VARCHAR(20) NOT NULL, expires_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE FengTu_PL_Email_Sent_Log (id BIGINT AUTO_INCREMENT PRIMARY KEY, confirmation_id VARCHAR(64), account_email VARCHAR(320) NOT NULL, recipients_json LONGTEXT NOT NULL, subject VARCHAR(998), attachment_json LONGTEXT, status VARCHAR(20) NOT NULL, error_message LONGTEXT, sent_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX FengTu_PL_Email_Sent_Status_Idx ON FengTu_PL_Email_Sent_Log(status, sent_at);
CREATE TABLE FengTu_PL_Email_Archive (id BIGINT AUTO_INCREMENT PRIMARY KEY, account_id BIGINT NOT NULL, account_email VARCHAR(320) NOT NULL, folder VARCHAR(500) NOT NULL, message_uid VARCHAR(255) NOT NULL, subject VARCHAR(998), from_address VARCHAR(1000), recipients_json LONGTEXT, sent_at TIMESTAMP, received_at TIMESTAMP, has_attachment BOOLEAN NOT NULL DEFAULT FALSE, body_preview VARCHAR(500), eml_path VARCHAR(2000) NOT NULL, archived_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(account_id, folder, message_uid));
CREATE INDEX FengTu_PL_Email_Archive_Query_Idx ON FengTu_PL_Email_Archive(account_id, sent_at, subject);
